import json,sys
d=json.load(sys.stdin)
for p in d['projects']:
    name=p['path'].split('/')[-1]
    for f in p['frameworks']:
        for pkg in f['topLevelPackages']:
            print(f'{name}: {pkg[\"id\"]} {pkg[\"resolvedVersion\"]}')
